<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {usePhasePage} from '../phasePage'
import type {CompliancePolicy,LegalReference} from '../complianceTypes'
import BusinessSteps from '../components/BusinessSteps.vue'
import ComplianceRuleFields from '../components/ComplianceRuleFields.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,base,english,loading,busy,failure,notice,load,write}=usePhasePage()
const step=ref(0),items=ref<CompliancePolicy[]>([]),draft=ref<CompliancePolicy|null>(null),reviewed=ref(false)
function refresh(){void load(()=>api().get<CompliancePolicy[]>('/compliance-policies'),v=>items.value=v)}
function edit(p:CompliancePolicy){draft.value=JSON.parse(JSON.stringify(p));reviewed.value=false;step.value=1}
function initial(){void load(()=>api().get<LegalReference>('/compliance-reference'),r=>{draft.value={...r,id:crypto.randomUUID(),version:0,effectiveFrom:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Singapore'}),effectiveTo:`${new Date().getFullYear()}-12-31`,status:'draft'};reviewed.value=false;step.value=1})}
function save(publish:boolean){const d=draft.value;if(!d||publish&&!reviewed.value)return;void write(async()=>{const p=await api().put<CompliancePolicy>('/compliance-policies/'+d.id,{expectedVersion:d.version,name:d.name,effectiveFrom:d.effectiveFrom,effectiveTo:d.effectiveTo,publish,rules:d.rules,sources:d.sources});draft.value=p;reviewed.value=false;step.value=publish?3:2},refresh)}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{english()?'Leave and contract policies':'假期与合同政策'}}</h2></header><p class="wf-hint">{{english()?'Review official references, publish a version, then adopt it for each employee. Existing payroll remains frozen.':'先核对官方依据与参数，发布版本后再给员工采用。修改会新增版本，保留历史依据及正式工资。'}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><BusinessSteps v-model="step" :disabled="busy" :steps="english()?['Choose policy','Review rules','Review sources & publish','Adopt for employees']:['选择政策','核对规则','核对依据并发布','员工采用']"/><template v-if="home?.headOffice&&home.employeeManage"><div v-show="step===0"><button class="primary" :disabled="busy||loading" @click="initial">{{english()?'Load official reference as draft':'载入官方参考草稿'}}</button><p class="wf-hint">{{english()?'References are not active until reviewed and published.':'参考草稿不会自动启用；请核对来源日期与公司适用范围。'}}</p><article v-for="p in items" :key="p.id" class="wf-history"><header class="wf-toolbar"><strong>{{p.name}} · v{{p.version}}</strong><button @click="edit(p)">{{english()?'Create next version':'核对／新增版本'}}</button></header><p>{{p.status==='published'?(english()?'Published':'已发布'):(english()?'Draft':'草稿')}} · {{p.effectiveFrom}} – {{p.effectiveTo}}</p><details><summary>{{english()?'Adopted evidence':'版本依据'}}</summary><p v-for="s in p.sources" :key="s.code"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}}</a> · {{s.checkedOn}}<br>{{s.summary}}</p></details></article></div><form v-if="draft" @submit.prevent="save(false)"><fieldset :disabled="busy"><div v-show="step===1"><div class="wf-grid"><label>{{english()?'Policy name':'政策名称'}}<input v-model="draft.name" maxlength="100" required></label><label>{{english()?'Effective from':'有效开始'}}<input v-model="draft.effectiveFrom" type="date" required></label><label>{{english()?'Effective to':'有效截止'}}<input v-model="draft.effectiveTo" type="date" required></label></div><ComplianceRuleFields :rules="draft.rules" :english="english()"/><footer class="wf-form-actions"><button type="button" class="primary" @click="step=2">{{english()?'Next: sources':'下一步：核对依据'}}</button></footer></div><div v-show="step===2"><h3>{{english()?'Official evidence stored with this version':'随政策版本保存的官方依据'}}</h3><article v-for="s in draft.sources" :key="s.code" class="wf-history"><label>{{english()?'Title':'资料标题'}}<input v-model="s.title" maxlength="200" required></label><div class="wf-grid"><label>{{english()?'Official URL':'官方链接'}}<input v-model="s.url" type="url" maxlength="2048" required><a :href="s.url" target="_blank" rel="noopener noreferrer">{{english()?'Open source':'查看官方原文'}}</a></label><label>{{english()?'Checked on':'核对日期'}}<input v-model="s.checkedOn" type="date" required></label></div><label>{{english()?'Applicable rule summary':'适用规定摘要'}}<textarea v-model="s.summary" rows="3" maxlength="3000" required/></label></article><label class="wf-check"><input v-model="reviewed" type="checkbox">{{english()?'I verified the current sources, parameters and applicability.':'已核对当前官方依据、参数及适用范围。'}}</label><footer class="wf-form-actions"><button type="button" @click="step=1">{{english()?'Previous':'上一步'}}</button><button type="submit">{{english()?'Save draft':'保存草稿'}}</button><button type="button" class="primary" :disabled="!reviewed" @click="save(true)">{{english()?'Publish new version':'发布新版本'}}</button></footer></div></fieldset></form><div v-show="step===3"><h3>{{english()?'Next: confirm employee contracts':'下一步：确认员工合同'}}</h3><p>{{english()?'Open an employee and choose Contract & leave. Existing adoptions keep their pinned policy version until reviewed.':'进入员工资料的「合同与假期」，核对工时、工作类别及期初余额。已有采用不会随政策修改自动覆盖。'}}</p><RouterLink class="wf-button primary" :to="base+'/employees'">{{english()?'Choose employee':'选择员工办理'}}</RouterLink></div><p v-if="!draft&&step!==0&&step!==3" class="wf-hint">{{english()?'Choose a policy first.':'请先选择或载入政策草稿。'}}</p></template><p v-else>{{english()?'Head office employee management permission required.':'需要总部员工管理权限。'}}</p></section></template>
